using System.Collections.Generic;
using UnityEngine;

public class PowerModule : PrimaryModule, IReactorModule
{
    /// <summary>
    /// Bars of energy generated per second.
    /// </summary>
    public float power = 1;
    
    // /// <summary>
    // /// Type of energy generated by module.
    // /// </summary>
    // public Common.SoundType soundType = Common.SoundType.None;

    public override string Description()
    {
        return "Generates energy for the reactor. Chaining power modules will increase overall output.";
    }

    public override string Info()
    {
        return $"Currently generating {power} untyped energy per second.";
    }

    public override bool Warning(out string message)
    {
        var warn = base.Warning(out message);
        var rack = GetComponentInParent<ModuleRack>();
        if (rack != null)
        {
            if (rack is Reactor)
            {
                if (warn)
                {
                    return true;
                }
                return false;
            }
        }
        message += "This module will not generate power at maximum efficiency unless placed in reactor.\n";
        return true;
    }

    public Dictionary<Common.SoundType, float> ChangeEnergy(Dictionary<Common.SoundType, float> energy)
    {
        var rack = GetComponentInParent<ModuleRack>();
        if (rack == null || rack.stunTimer > 0)
        {
            return energy;
        }
        
        if (rack is not Reactor)
        {
            energy[Common.SoundType.Pure] += .25f * power;
        }
        else
        {
            energy[Common.SoundType.Pure] += power;
        }
        return energy;
    }

    // public IReactorModule.ReactorStats MyReactorStats()
    // {
    //     return new IReactorModule.ReactorStats()
    //     {
    //         PowerGenerated = power
    //     };
    // }
    public override Dictionary<string, float> ChangeMusicParams(Dictionary<string, float> musicParams)
    {
        throw new System.NotImplementedException();
    }
}
